package runner

import (
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// transcript is the conversation's record file, in the layout Cursor keeps
// (recorded: runs/*/samples/*/transcript): one JSON line per message, a user
// message first, assistant messages with their text and tool calls, and a
// closing turn_ended line. It is what the scenario script reads as
// A10N_MOCK_SESSION_FILE.
type transcript struct{ path string }

var nonAlnum = regexp.MustCompile(`[^A-Za-z0-9]`)

// newTranscript names the session's file under <home>/.cursor/projects/<project>/
// agent-transcripts/<session>/, where <project> is the workspace path (symlinks
// resolved by the entrypoint) with every non-alphanumeric character as "-". The
// file itself is written with the first record, after the start hook has run.
//
// sr:provides session-transcript-file/cursor
// sr:docs https://cursor.com/docs/hooks#common-schema
func newTranscript(home, dir, session string) (*transcript, error) {
	project := nonAlnum.ReplaceAllString(strings.TrimPrefix(dir, "/"), "-")
	d := filepath.Join(home, ".cursor", "projects", project, "agent-transcripts", session)
	if err := os.MkdirAll(d, 0o755); err != nil {
		return nil, err
	}
	return &transcript{path: filepath.Join(d, session+".jsonl")}, nil
}

func (t *transcript) add(line any) {
	b, _ := json.Marshal(line)
	if f, err := os.OpenFile(t.path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644); err == nil {
		_, _ = f.Write(append(b, '\n'))
		_ = f.Close()
	}
}

func (t *transcript) message(role string, blocks ...map[string]any) {
	t.add(map[string]any{"role": role, "message": map[string]any{"content": blocks}})
}

func (t *transcript) user(prompt string) {
	t.message("user", map[string]any{"type": "text", "text": "<user_query>\n" + prompt + "\n</user_query>"})
}

func (t *transcript) text(s string) {
	t.message("assistant", map[string]any{"type": "text", "text": s})
}

func (t *transcript) toolUse(name string, input map[string]any) {
	t.message("assistant", map[string]any{"type": "tool_use", "name": name, "input": input})
}

func (t *transcript) end() { t.add(map[string]any{"type": "turn_ended", "status": "success"}) }

func (t *transcript) exists() bool { _, err := os.Stat(t.path); return err == nil }
// Package transcript is the harness-neutral core of a session's transcript: the
// file it lives in, its creation, and the bookkeeping on its records.
package transcript

import (
	"os"
	"path/filepath"
)

// Layout is how a harness keys its transcript files under its configuration
// directory: a projects directory, one subdirectory per working directory, one
// file per session.
type Layout struct {
	// ProjectsDir is the directory under the configuration directory that holds
	// one subdirectory per working directory.
	ProjectsDir string
	// Encode is the subdirectory name of a (symlink-resolved) working directory.
	Encode func(dir string) string
	// Ext is the transcript file's extension, dot included.
	Ext string
}

// ResolveDir is dir with its symlinks resolved, or dir itself when it cannot be
// (a directory that does not exist yet): the form a harness keys a session by
// and reports in its payloads.
func ResolveDir(dir string) string {
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		return resolved
	}
	return dir
}

// ProjectDir is the directory holding the transcripts of sessions run in cwd.
func (l Layout) ProjectDir(configDir, cwd string) string {
	return filepath.Join(configDir, l.ProjectsDir, l.Encode(ResolveDir(cwd)))
}

// FilePath is the transcript of session sessionID run in cwd: under the
// configuration directory, keyed by cwd with its symlinks resolved and by the
// session id.
//
// sr:capability session-transcript-file
func (l Layout) FilePath(configDir, cwd, sessionID string) string {
	return filepath.Join(l.ProjectDir(configDir, cwd), sessionID+l.Ext)
}

// Lazy is a transcript file that does not exist until the first record is
// written: a fresh session's file is absent while the session's start hook
// runs. It also separates the path records go to from the path a harness
// reports for it, which differ for a session resumed from another directory.
type Lazy struct {
	// Path is where records are written.
	Path string
	// Reported is what hook payloads carry as the transcript's path.
	Reported string

	f     *os.File
	fresh bool
}

